import os
from pathlib import Path
import csv

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
dates = ["20190125", "20190126", "20190127", "20190128", "20190129"]
targets = [("石家庄站", "永清站"), ("南京站", "南通站")]
lines = ["陕京二线", "冀宁线"]

# accumulate per (line, segment)
acc = {ln: {seg: 0.0 for seg in targets} for ln in lines}
per_day = {ln: {seg: {} for seg in targets} for ln in lines}
missing = []

for dt in dates:
    fp = DIR / f"{dt}_pipeline.csv"
    if not fp.exists():
        missing.append(dt)
        continue
    with open(fp, newline="", encoding="utf-8") as f:
        r = csv.reader(f)
        header = next(r)
        for row in r:
            if len(row) < 5:
                continue
            start, end, typ, line, flow = row[0], row[1], row[2], row[3], row[4]
            seg = (start, end)
            if line in lines and seg in targets:
                try:
                    v = abs(float(flow))
                except ValueError:
                    continue
                acc[line][seg] += v
                per_day[line][seg][dt] = v

print("=== per-day values ===")
for ln in lines:
    for seg in targets:
        print(ln, seg, per_day[ln][seg])
print("=== cumulative (sum of abs over 5 days) ===")
for ln in lines:
    for seg in targets:
        print(ln, seg, round(acc[ln][seg], 3))
print("missing:", missing)

