import os
import csv
from pathlib import Path
from statistics import pstdev

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
dates = ["20190203", "20190204"]
data = {}  # (start, end) -> {date: flow}
for d in dates:
    with open(DIR / f"{d}_pipeline.csv", newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            if row["管道划分"] == "西气东输三线":
                key = (row["起点站名"], row["终点站名"])
                data.setdefault(key, {})[d] = float(row["管道流量"])

results = []
for key, vals in data.items():
    if len(vals) == 2:
        results.append((pstdev(list(vals.values())), key, vals))
results.sort(key=lambda x: -x[0])
for std, key, vals in results:
    print(f"{key[0]} -> {key[1]} | std={std:.4f} | " +
          " | ".join(f"{d}:{v}" for d, v in sorted(vals.items())))

import os
import csv
from pathlib import Path
from decimal import Decimal

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
dates = ["20190223", "20190307"]
targets = ["西气东输二线", "冀宁线"]

daily = {}
for d in dates:
    p = DIR / f"{d}_pipeline.csv"
    sums = {t: Decimal("0") for t in targets}
    with open(p, newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            line = row["管道划分"].strip()
            if line in sums:
                sums[line] += Decimal(row["管道流量"])
    daily[d] = sums

for d in dates:
    print(d, {k: str(v) for k, v in daily[d].items()})

tot = {t: sum(daily[d][t] for d in dates) for t in targets}
print("window_total", {k: str(v) for k, v in tot.items()})
print("diff", str(tot["西气东输二线"] - tot["冀宁线"]))

