import os
import csv
from pathlib import Path

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
dates = ["20190127", "20190128", "20190129", "20190130", "20190202"]
targets = ["陕京二线", "川气东送"]
totals = {t: 0.0 for t in targets}
daily = {t: {} for t in targets}

for d in dates:
    p = DIR / f"{d}_pipeline.csv"
    with open(p, newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            line = row["管道划分"].strip()
            if line in targets:
                v = float(row["管道流量"])
                totals[line] += v
                daily[line][d] = daily[line].get(d, 0.0) + v

for t in targets:
    print(t, {k: round(v, 3) for k, v in daily[t].items()}, "total=", round(totals[t], 3))
print("diff(川气东送-陕京二线)=", round(totals["川气东送"] - totals["陕京二线"], 3))

import os
import csv
from pathlib import Path
from statistics import pstdev, stdev

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
dates = ["20190114", "20190115", "20190116", "20190119", "20190120", "20190121"]

seg = {}  # (start, end) -> {date: flow}
for d in dates:
    p = DIR / f"{d}_pipeline.csv"
    with open(p, newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            if row["管道划分"] == "西气东输一线":
                key = (row["起点站名"], row["终点站名"])
                seg.setdefault(key, {})[d] = float(row["管道流量"])

results = []
for key, vals in seg.items():
    if len(vals) != len(dates):
        continue
    xs = [vals[d] for d in dates]
    results.append((pstdev(xs), stdev(xs), key, vals))

results.sort(key=lambda r: r[0], reverse=True)
for p, s, key, vals in results:
    print(f"{key[0]} -> {key[1]} | pstdev={p:.3f} | sample_std={s:.3f}")
    for d in dates:
        print(f"   {d}: {vals[d]}")

import os, csv
from pathlib import Path
from decimal import Decimal

DIR = Path(os.environ["NODE_FLOW_DIR"])
dates = ["20191106", "20191107", "20191118"]
targets = ["靖边站", "南通站"]
totals = {t: Decimal(0) for t in targets}
detail = {t: {} for t in targets}

for d in dates:
    p = DIR / f"{d}_node.csv"
    with open(p, newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            name = row["站名"].strip()
            if name in targets:
                inp = row.get("输入流量", "").strip()
                calc = row.get("计算流量", "").strip()
                val = Decimal(inp) if inp else (Decimal(calc) if calc else None)
                if val is None:
                    continue
                v = abs(val)
                totals[name] += v
                detail[name].setdefault(d, []).append((row["管道划分"], str(v)))

for t in targets:
    print(t, "total:", totals[t])
    for d, items in detail[t].items():
        print(" ", d, items)
